<template><div><div class="page-head"><div><h1>Exam questions</h1><p>Create and maintain the official entrance assessment question bank.</p></div><button v-if="auth.canManageExam" class="primary" @click="edit()">Add question</button></div><section class="panel"><div class="toolbar"><input v-model="search" placeholder="Search question text" @input="delayed"><select v-model="category" @change="load"><option value="">All categories</option><option v-for="c in categories" :key="c">{{c}}</option></select></div><div v-if="error" class="error">{{error}}</div><div class="table-wrap"><table><thead><tr><th>No.</th><th>Question</th><th>Category</th><th>Difficulty</th><th>Answer</th><th>Action</th></tr></thead><tbody><tr v-for="q in page.data" :key="q.id"><td>{{q.question_number}}<small v-if="!q.is_active"> (inactive)</small></td><td><strong>{{q.question_text}}</strong></td><td>{{q.category}}</td><td><span class="status">{{q.difficulty_level}}</span></td><td>{{q.correct_answer}}</td><td><button v-if="auth.canManageExam" class="secondary" @click="edit(q)">Edit</button></td></tr></tbody></table></div><div class="pagination"><button class="secondary" :disabled="!page.prev_page_url" @click="load(page.current_page-1)">Previous</button><button class="secondary" :disabled="!page.next_page_url" @click="load(page.current_page+1)">Next</button></div></section><div v-if="form" class="modal-wrap" @click.self="form=null"><form class="modal" @submit.prevent="save"><p v-if="error" role="alert" class="error">{{error}}</p><h2>{{form.id?'Edit':'Add'}} question</h2><div class="form-grid"><div class="field"><label>Question number</label><input v-model.number="form.question_number" type="number" min="1" required></div><div class="field"><label>Category</label><select v-model="form.category" required><option v-for="c in categories" :key="c">{{c}}</option></select></div><div class="field full"><label>Question text</label><textarea v-model="form.question_text" required></textarea></div><div v-for="letter in ['a','b','c','d']" :key="letter" class="field"><label>Option {{letter.toUpperCase()}}</label><input v-model="form[`option_${letter}`]" required></div><div class="field"><label>Correct answer</label><select v-model="form.correct_answer"><option>A</option><option>B</option><option>C</option><option>D</option></select></div><div class="field"><label>Difficulty</label><select v-model="form.difficulty_level"><option>easy</option><option>medium</option><option>hard</option></select></div></div><label><input type="checkbox" v-model="form.is_active"> Active for new exams</label><p>Changes affect new sessions only. Each new attempt randomly selects 20 active questions per topic and shuffles both topic and question order.</p><div class="modal-actions"><button v-if="form.id" type="button" class="danger" @click="remove">Delete</button><button type="button" class="secondary" @click="form=null">Cancel</button><button class="primary">Save question</button></div></form></div></div></template>
<script setup>import{onMounted,ref}from'vue';import api,{errorMessage}from'../utils/api';import{useAdminAuth}from'../stores/auth';const auth=useAdminAuth(),page=ref({data:[]}),search=ref(''),category=ref(''),form=ref(null),error=ref(''),categories=['General Mathematics','Science','Reading Comprehension','Logical Reasoning','Digital Literacy'];let timer;const load=async(p=1)=>{page.value=(await api.get('/admin/questions',{params:{page:p,search:search.value,category:category.value}})).data};const delayed=()=>{clearTimeout(timer);timer=setTimeout(load,300)};const edit=q=>form.value=q?{...q}:{question_number:'',question_text:'',category:categories[0],option_a:'',option_b:'',option_c:'',option_d:'',correct_answer:'A',difficulty_level:'medium',is_active:true};const save=async()=>{try{form.value.id?await api.put(`/admin/questions/${form.value.id}`,form.value):await api.post('/admin/questions',form.value);form.value=null;load()}catch(e){error.value=errorMessage(e)}};const remove=async()=>{if(!confirm('Delete this question?'))return;try{await api.delete(`/admin/questions/${form.value.id}`);form.value=null;load()}catch(e){error.value=errorMessage(e)}};onMounted(load)</script>
